リポジトリの構造を確認するために、まずファイルを分析します。

タスクは、Osk と Fen を同時に 'nim' から 'pex' へ進める新しい operation 'advanceOskFen' を追加することです。

現在のファイル構造から、以下を実装する必要があります：

1. `src/vok/rules.ts` に新しい operation ルールを追加
2. `src/protocol_adapter.ts` で operation を登録

ファイル内容を確認して、適切な変更を加えます。

<modified_files>
{
  "src/vok/rules.ts": "import { Operation, WorldState } from '../types';

export const rules = {
  advanceOsk: (state: WorldState): WorldState => {
    return {
      ...state,
      osk: state.osk === 'nim' ? 'pex' : state.osk,
    };
  },
  advanceFen: (state: WorldState): WorldState => {
    return {
      ...state,
      fen: state.fen === 'nim' ? 'pex' : state.fen,
    };
  },
  advanceOskFen: (state: WorldState): WorldState => {
    return {
      ...state,
      osk: state.osk === 'nim' ? 'pex' : state.osk,
      fen: state.fen === 'nim' ? 'pex' : state.fen,
    };
  },
};
",
  "src/protocol_adapter.ts": "import { WorldProtocol, WorldState, Operation, EntitySnapshot } from './types';
import { rules } from './vok/rules';

let currentState: WorldState = {
  osk: 'nim',
  fen: 'nim',
};

export const protocol: WorldProtocol = {
  reset: () => {
    currentState = {
      osk: 'nim',
      fen: 'nim',
    };
  },
  applyOperation: (operation: Operation) => {
    if (operation.type === 'advanceOsk') {
      currentState = rules.advanceOsk(currentState);
    } else if (operation.type === 'advanceFen') {
      currentState = rules.advanceFen(currentState);
    } else if (operation.type === 'advanceOskFen') {
      currentState = rules.advanceOskFen(currentState);
    }
  },
  getEntityState: (entityId: string): EntitySnapshot | null => {
    if (entityId === 'osk') {
      return { id: 'osk', state: currentState.osk };
    } else if (entityId === 'fen') {
      return { id: 'fen', state: currentState.fen };
    }
    return null;
  },
  toAbstractSnapshot: (): WorldState => {
    return currentState;
  },
};
"
}
